export function translateMarketingText(value, language) {
  if (language !== 'en' || typeof value !== 'string') return value;
  const parts = value.match(/^(\s*)([\s\S]*?)(\s*)$/);
  const leading = parts?.[1] || '';
  const text = parts?.[2] || '';
  const trailing = parts?.[3] || '';
  if (!text) return value;
  const source = text.replace(/\s+/g, ' ');
  let translated = EN_TRANSLATIONS[source];

  if (!translated) {
    const apartmentLimit = source.match(/^Tot ([\d.,]+) appartementen$/);
    const customQuote = source.match(/^Voor ([\d.,]+) appartementen maken wij een offerte op maat\.$/);
    const choosePlan = source.match(/^Kies (.+)$/);
    const monthlyPrice = source.match(/^(.+) \/ maand$/);
    if (apartmentLimit) translated = `Up to ${apartmentLimit[1]} apartments`;
    else if (customQuote) translated = `For ${customQuote[1]} apartments, we will prepare a custom quote.`;
    else if (choosePlan) translated = `Choose ${choosePlan[1]}`;
    else if (monthlyPrice) translated = `${monthlyPrice[1]} / month`;
    else translated = source;
  }

  return `${leading}${translated}${trailing}`;
}

export function translateMarketingNode(node, language) {
  if (typeof node === 'string') return translateMarketingText(node, language);
  if (Array.isArray(node)) return node.map((child) => translateMarketingNode(child, language));
  if (!isValidElement(node) || node.props?.children == null) return node;
  return cloneElement(node, undefined, translateMarketingNode(node.props.children, language));
}
